1	// grow_with_claudinite task: growth-extract — the growth lifecycle's CAPTURE
2	// stage (per-project-scheduling DESIGN §6). ONE task over BOTH lesson sources:
3	// it runs the extract-from-activity skill over the window's commits/PRs/issues
4	// and the extract-from-conversations skill over the captured conversation logs,
5	// then runs prose-to-checks over what it just wrote to see whether any of it
6	// upgrades to a check — and lands the whole run through a single PR that
7	// auto-merges once the repo's checks pass. Worker: task.md.
8	//
9	// The two halves were separate tasks (growth-extract + conversation-extract)
10	// firing in the same daily slot, each opening its own PR against the same local
11	// packs on the same night. They shared the lesson bar, the promotion ladder, the
12	// dedup surface and the landing mechanics, so splitting them bought nothing and
13	// cost a second opus dispatch, a second PR, and two runs deduping against a
14	// corpus the other one was concurrently writing. One task, two source skills.
15	//
16	// Self-contained (imports nothing): the whole contract is this default export.
17	
18	export default {
19	  id: 'growth-extract',
20	  frequency: 'daily-1h',           // the 03:00 slot — lessons captured from an already-converged mount (DESIGN §2)
21	  precondition_signals: ['commits', 'prs', 'issues', 'conversationLogs'],
22	  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and auto-merge means no human reviews the PR
23	  expected_outcome: 'merged-pr',            // additive edits to the repo's own local packs; arms auto-merge after CI
24	  agent_instructions: 'task.md',
25	  agent_execution_timeout: 2700,            // two source passes plus the prose-to-checks upgrade — generous bound, extreme protection
26	
27	  // TWO independent reasons to run, and the Context says which halves are live:
28	  //
29	  //   (a) a SUBSTANTIVE default-branch change — a bot bump / [skip ci] /
30	  //       nightly-baselining commit advancing main is not a lesson to extract, so
31	  //       `commits.substantiveChange` already applies that classification. This
32	  //       arms the activity half AND means a fresh capture now sits on the logs
33	  //       branch, so the conversation half runs too.
34	  //   (b) a log on the branch is ACTUALLY past retention — aged material to give a
35	  //       final hindsight pass and prune, regardless of activity, so the prune
36	  //       still fires on a quiet repo (a log ages out on wall time, not on the
37	  //       repo changing). (b) tests the AGE, not just "a branch exists and
38	  //       retention is configured": that pair is true on every capturing repo
39	  //       every day, which dispatched an opus agent daily to find nothing prunable.
40	  //
41	  // The activity half is scoped by the substantive shas + touched PR/issue numbers
42	  // passed as binding scope — INCLUDING the PRs merged during the window, whose
43	  // review discussion is usually its richest lesson source. Context is binding
44	  // scope and task.md forbids widening past it, so a merged PR the precondition
45	  // does not name is unreadable to the worker. When only (b) fired, Context says
46	  // so explicitly, so a quiet-but-aged run skips the activity half rather than
47	  // inventing a window for it.
48	  precondition(signals) {
49	    const commits = signals.commits ?? {};
50	    const substantive = commits.substantiveChange === true;
51	    const logs = signals.conversationLogs ?? {};
52	    const retention = logs.retentionDays;
53	    const oldest = logs.oldestLogAgeDays;
54	    const configured = logs.present === true && typeof retention === 'number';
55	    const aged = configured && typeof oldest === 'number' && oldest > retention;
56	
57	    if (!substantive && !aged) {
58	      if (configured) return { run: false, reason: `no substantive default-branch change and no log older than retention ${retention}d — nothing to extract or prune` };
59	      return { run: false, reason: logs.present ? 'no substantive default-branch change and retention unset — nothing to extract or prune' : 'no substantive default-branch change and no logs branch' };
60	    }
61	
62	    const context = [];
63	    const reasons = [];
64	
65	    if (substantive) {
66	      const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
67	      const prs = signals.prs?.touched ?? [];
68	      const merged = (signals.prs?.merged ?? []).map((p) => p.number);
69	      const issues = signals.issues?.touched ?? [];
70	      reasons.push(`${shas.length} substantive commit(s) in the window`);
71	      context.push(`Activity half IS in scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`);
72	      if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
73	      if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
74	      if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
75	      context.push('Conversation half IS in scope: a substantive merge means fresh captures on origin/conversation-logs — run the fresh pass over the recent window.');
76	    } else {
77	      context.push('Activity half is NOT in scope: no substantive default-branch change in the window. Skip extract-from-activity entirely — do not invent a window for it.');
78	    }
79	
80	    if (aged) {
81	      reasons.push(`oldest log ${oldest.toFixed(1)}d old vs retention ${retention}d`);
82	      context.push(`Retention prune IS due: the oldest log is ${oldest.toFixed(1)}d old against retention ${retention}d. Every log past ${retention}d gets its final hindsight pass, then is removed from the logs branch.`);
83	    } else if (substantive && configured) {
84	      context.push(`Retention prune is NOT due: no log is older than retention ${retention}d. Delete nothing.`);
85	    } else if (substantive) {
86	      context.push('Retention prune is NOT due: retention is unset for this repo. Delete nothing (capture-only adoption).');
87	    }
88	
89	    return { run: true, reason: reasons.join('; '), context };
90	  },
91	};
