1	// Deliver GENERATED files on an auto-merging pull request — the write half of an
2	// agentless task whose whole output is a regenerated file.
3	//
4	// It exists because two tasks need exactly this and must not each grow their own
5	// copy: the per-repo skill-usage fold and the sheepdog's fleet aggregate both
6	// recompute a `*.GENERATED.json` from scratch and want it landed without a human in
7	// the loop. (baselining's own `deliver` is deliberately NOT folded in here: it
8	// commits a whole working tree, honours the member's `maintenance.delivery`
9	// preference, and reuses a dated family branch — a different job that happens to end
10	// in a PR too.)
11	//
12	// Two properties everything here is shaped around:
13	//
14	//   NOTHING TOUCHES THE CHECKOUT. The scheduler runs every due task in ONE checkout,
15	//   so a task that checks a branch out hands the next task a tree it did not expect.
16	//   Every write goes through git plumbing (hash-object / read-tree into a throwaway
17	//   index / write-tree / commit-tree / push), against the fetched base tip — HEAD,
18	//   the index and the working tree are never touched, and there is nothing to clean
19	//   up if the run dies.
20	//
21	//   THE BASE IS THE ONLY AUTHORITY. Both the prior state a generator reads and the
22	//   tree it builds on come from the remote base branch, never from local HEAD. A
23	//   previous run's PR still sitting open is simply rebuilt from the base, so a
24	//   stateless generator stays idempotent no matter how many runs stack up.
25	//
26	// Idempotence is the caller's to keep: pass files whose content is a pure function of
27	// the inputs, and compare against `readAtBase` before calling — an identical
28	// recompute should open nothing at all.
29	
30	import { execFileSync } from 'node:child_process';
31	import { rmSync } from 'node:fs';
32	import { tmpdir } from 'node:os';
33	import { join } from 'node:path';
34	
35	const API = 'https://api.github.com';
36	
37	const git = (root, args, opts = {}) => execFileSync('git', ['-C', root, ...args], {
38	  encoding: 'utf8',
39	  // A generated file can be large, and a `git show` of one easily tops spawn's
40	  // default 1 MiB buffer — which fails as a truncated read, not as an error.
41	  maxBuffer: 256 * 1024 * 1024,
42	  // stdin is 'pipe' exactly when there is input to pipe: an explicit 'ignore' with an
43	  // `input` set silently feeds the child NOTHING, and `hash-object --stdin` then
44	  // cheerfully writes the empty blob — a wrong answer, not an error.
45	  stdio: [opts.input === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'],
46	  ...opts,
47	});
48	
49	async function gh(token, path, { method = 'GET', body } = {}) {
50	  const res = await fetch(`${API}${path}`, {
51	    method,
52	    headers: {
53	      authorization: `Bearer ${token}`,
54	      accept: 'application/vnd.github+json',
55	      'x-github-api-version': '2022-11-28',
56	      ...(body ? { 'content-type': 'application/json' } : {}),
57	    },
58	    body: body ? JSON.stringify(body) : undefined,
59	  });
60	  let json = null;
61	  try { json = await res.json(); } catch { /* empty body */ }
62	  return { status: res.status, json };
63	}
64	
65	// Auto-merge is a GraphQL-only mutation. Best effort by design, and re-asserted on
66	// every run: a repo that had auto-merge disabled when the PR was opened would
67	// otherwise leave that PR open forever with nothing that could ever arm it.
68	async function enableAutoMerge(token, pullRequestId) {
69	  const res = await fetch(`${API}/graphql`, {
70	    method: 'POST',
71	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
72	    body: JSON.stringify({
73	      query: 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}',
74	      variables: { id: pullRequestId },
75	    }),
76	  });
77	  const json = await res.json().catch(() => null);
78	  if (json?.errors?.length) throw new Error(json.errors[0].message);
79	}
80	
81	export const remoteUrl = (repo, token) => `https://x-access-token:${token}@github.com/${repo}.git`;
82	
83	// The base branch's remote tip, fetched into this checkout's object store. Read from
84	// the REMOTE, never from HEAD — see the header.
85	export function baseTip(root, remote, base) {
86	  git(root, ['fetch', '--quiet', remote, base]);
87	  return git(root, ['rev-parse', 'FETCH_HEAD']).trim();
88	}
89	
90	// One file's content at a commit, or null when the path does not exist there.
91	export function readAt(root, sha, path) {
92	  try { return git(root, ['show', `${sha}:${path}`]); } catch { return null; }
93	}
94	
95	// Commit `files` ({ path: content }) onto the base tip and push to `branch`,
96	// force — the content is regenerated wholesale each run, so the branch is a
97	// regenerate-not-reconcile surface.
98	export function pushGenerated(root, { remote, baseSha, branch, files, message }) {
99	  const index = join(tmpdir(), `claudinite-deliver-${process.pid}-${Date.now()}.index`);
100	  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
101	  try {
102	    plumb(['read-tree', baseSha]);
103	    for (const [path, content] of Object.entries(files)) {
104	      const blob = git(root, ['hash-object', '-w', '--stdin'], { input: content }).trim();
105	      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
106	    }
107	    const tree = plumb(['write-tree']).trim();
108	    const commit = git(root, [
109	      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
110	      'commit-tree', tree, '-p', baseSha, '-m', message,
111	    ]).trim();
112	    git(root, ['push', '--quiet', '--force', remote, `${commit}:refs/heads/${branch}`]);
113	    return commit;
114	  } finally { rmSync(index, { force: true }); }
115	}
116	
117	// Deliver `files` on an auto-merging PR. An open PR whose head branch carries
118	// `branchPrefix` is REUSED — a daily regenerate that runs before yesterday's PR
119	// merged updates that PR rather than stacking a second one — otherwise a
120	// `<branchPrefix>/<stamp>` branch is minted and a PR opened on it.
121	//
