1	// The usage-fold preprocessing entry point — the script the scheduler runs as
2	// `node worker.mjs` (cwd = this task dir, bounded by prework_timeout).
3	// The whole task: no agent, no dispatch issue.
4	//
5	// It holds NO counting logic. The counting and folding are `fold-usage.mjs`, its
6	// SIBLING in this task folder — nothing outside this task uses them, so that is
7	// where they live and where their tests point. This file is the I/O shell:
8	//
9	//   1. fetch the orphan `conversation-logs` branch (plain local git — the branch is
10	//      in this repo, so one tree read plus one blob read per file beats any REST
11	//      round-trip, and there is no rate budget to spend);
12	//   2. count each capture file still in the raw retention window;
13	//   3. read the scheduler's own task-run records from its Actions logs, past the
14	//      `runsFoldedThrough` watermark (read-task-runs.mjs) — the second source, and
15	//      the only one that sees a task that never opened a session at all;
16	//   4. fold: day rows recomputed from scratch, task rows appended once, week rows
17	//      advanced past the `foldedThrough` watermark (skill-usage-metrics DESIGN §5);
18	//   5. deliver the regenerated `.claudinite/local/usage.GENERATED.json` on an
19	//      auto-merging PR — and open NOTHING when the recompute is byte-identical.
20	//
21	// The aggregate lives under `.claudinite/local/` because that is the repo-owned area
22	// the vendoring refresh never touches; the mount root itself is read-only canon.
23	
24	import { execFileSync } from 'node:child_process';
25	import { readFileSync } from 'node:fs';
26	import { join } from 'node:path';
27	import { pathToFileURL } from 'node:url';
28	import { deliverGenerated, baseTip, readAt, remoteUrl } from '../../../../engine/scheduler/deliver-generated.mjs';
29	import { countEntries, foldUsage, mountedSkillNames } from './fold-usage.mjs';
30	import { makeReader, readTaskRuns } from './read-task-runs.mjs';
31	
32	const BRANCH = 'conversation-logs';
33	export const USAGE_PATH = '.claudinite/local/usage.GENERATED.json';
34	const PR_BRANCH_PREFIX = 'claudinite/usage-fold';
35	
36	const slotId = process.env.CLAUDINITE_SLOT_ID || '';
37	const log = (s) => console.log(`usage-fold${slotId ? ` [${slotId}]` : ''}: ${s}`);
38	
39	const git = (root, args) => execFileSync('git', ['-C', root, ...args], {
40	  encoding: 'utf8',
41	  // A capture blob easily tops the default 1 MiB buffer — a long session's log then
42	  // dies mid-read and the day it lands in silently under-counts.
43	  maxBuffer: 256 * 1024 * 1024,
44	  stdio: ['ignore', 'pipe', 'pipe'],
45	});
46	
47	// --- the raw window -----------------------------------------------------------
48	
49	// The capture filename standard (packs/grow_with_claudinite/README.md). Issue `0`
