  assert.equal(pullDisposition({ delivery: 'review', runs: [done('success')] }), 'keep');
  assert.equal(pullDisposition({ delivery: 'review', runs: [done('failure')] }), 'keep');
  assert.equal(pullDisposition({ delivery: 'review', runs: [] }), 'keep');
