  const yaml = [
    'name: Tests', 'on:', '  workflow_dispatch:', '  pull_request:',
    '    branches: [main]', '  push:', '    branches: [main, "claude/**"]',
    'jobs:', '  test:', '    runs-on: ubuntu-latest',
  ].join('\n');
