// Smoke harness for landDelivery(): drives the composed I/O path with a scripted
// fetch stub, one scenario per repo shape. Not a committed test (the corpus keeps
// REST I/O out of unit tests); this exists to prove the NEW composition executes
// the same call sequence the pre-refactor inline code did.
import assert from 'node:assert/strict';
import { landDelivery } from '/home/user/Claudinite/engine/scheduler/land-pr.mjs';

const CI_YML = Buffer.from('on:\n  workflow_dispatch:\n  pull_request:\njobs: {}\n').toString('base64');
const NO_DISPATCH_YML = Buffer.from('on:\n  pull_request:\njobs: {}\n').toString('base64');

function makeFetch(shape, calls) {
  return async (url, opts = {}) => {
    const method = opts.method ?? 'GET';
    const u = String(url);
    calls.push(`${method} ${u.replace('https://api.github.com', '')}`);
    const reply = (status, json) => ({ status, json: async () => json });

    if (u.endsWith('/graphql')) {
      return reply(200, shape.armError ? { errors: [{ message: shape.armError }] } : { data: {} });
    }
    if (u.includes('/contents/.github/workflows?')) {
      return reply(200, shape.workflows.map((w) => ({ name: w.name })));
    }
    if (u.includes('/contents/.github/workflows/')) {
      const name = decodeURIComponent(u.split('/contents/.github/workflows/')[1].split('?')[0]);
      const w = shape.workflows.find((x) => x.name === name);
      return reply(200, { content: w?.content ?? '' });
    }
    if (u.includes('/actions/workflows/') && u.endsWith('/dispatches')) return reply(204, null);
    if (u.includes('/branches/main')) return reply(200, { protected: shape.protected ?? false });
    if (u.includes('/rules/branches/main')) return reply(200, shape.rules ?? []);
    if (u.includes('/actions/runs?head_sha=')) return reply(200, { workflow_runs: shape.runs ?? [] });
    if (u.includes('/pulls/7/merge')) return reply(shape.mergeStatus ?? 200, { merged: true });
    if (u.includes('/git/refs/heads/')) return reply(204, null);
    throw new Error(`unstubbed: ${method} ${u}`);
  };
}

const PR = { number: 7, node_id: 'PR_x', head: { ref: 'claudinite/x/2026-08-07', sha: 'abc' } };
async function run(name, shape, delivery, expect) {
  const calls = [];
  global.fetch = makeFetch(shape, calls);
  const quiet = [];
  const out = await landDelivery({ token: 't', repo: 'o/r', base: 'main', pr: PR, delivery, log: (s) => quiet.push(s) });
  assert.equal(out.action, expect.action, `${name}: action`);
  assert.equal(out.merged, expect.merged, `${name}: merged`);
  for (const c of expect.mustCall ?? []) assert.ok(calls.some((x) => x.includes(c)), `${name}: expected a call matching "${c}"\n  got:\n  ${calls.join('\n  ')}`);
  for (const c of expect.mustNotCall ?? []) assert.ok(!calls.some((x) => x.includes(c)), `${name}: forbidden call "${c}" happened`);
  console.log(`ok  ${name} → action=${out.action} merged=${out.merged}`);
}

// 1. review member: checks are dispatched (owner reviews against a green), nothing merges or arms.
await run('review member', { workflows: [{ name: 'ci.yml', content: CI_YML }] }, 'review',
  { action: 'none', merged: false, mustCall: ['POST /repos/o/r/actions/workflows/ci.yml/dispatches'], mustNotCall: ['PUT /repos/o/r/pulls/7/merge', 'POST /graphql'] });

// 2. no PR CI anywhere: auto-merge means merge directly — the arm would be rejected clean-status forever.
await run('no PR CI → direct merge', { workflows: [] }, 'auto-merge',
  { action: 'merge', merged: true, mustCall: ['PUT /repos/o/r/pulls/7/merge'], mustNotCall: ['POST /graphql'] });

// 3. CI present, base requires nothing: skip the doomed arm, verify the dispatched run, land, tidy the branch.
await run('ungated base → land on evidence', {
  workflows: [{ name: 'ci.yml', content: CI_YML }],
  runs: [{ name: 'CI', status: 'completed', conclusion: 'success' }],
}, 'auto-merge', {
  action: 'land', merged: true,
  mustCall: ['PUT /repos/o/r/pulls/7/merge', 'DELETE /repos/o/r/git/refs/heads/'],
  mustNotCall: ['POST /graphql'],
});

// 4. gate present, arm succeeds: GitHub's queue owns the landing — no merge from here.
await run('gated base → arm, GitHub lands it', {
  workflows: [{ name: 'ci.yml', content: CI_YML }], protected: true,
}, 'auto-merge', { action: 'arm', merged: false, mustCall: ['POST /graphql'], mustNotCall: ['PUT /repos/o/r/pulls/7/merge'] });

// 5. gate present, arm REJECTED (auto-merge off) with a parked action_required run beside a green
//    dispatched run: the fallback lands on the concluded evidence — the #455/#205/#95 shape.
await run('failed arm → landNow fallback', {
  workflows: [{ name: 'ci.yml', content: CI_YML }], protected: true,
  armError: 'Auto-merge is not allowed on this repository',
  runs: [
    { name: 'CI', status: 'completed', conclusion: 'success' },
    { name: 'CI', status: 'completed', conclusion: 'action_required' },
  ],
}, 'auto-merge', { action: 'arm', merged: true, mustCall: ['POST /graphql', 'PUT /repos/o/r/pulls/7/merge'] });

// 6. failed arm over genuinely RED CI: nothing merges — the PR is left standing.
await run('failed arm + red CI → leaves the PR', {
  workflows: [{ name: 'ci.yml', content: NO_DISPATCH_YML }], protected: true,
  armError: 'Pull request is in unstable status',
  runs: [{ name: 'CI', status: 'completed', conclusion: 'failure' }],
}, 'auto-merge', { action: 'arm', merged: false, mustNotCall: ['PUT /repos/o/r/pulls/7/merge'] });

console.log('\nall landDelivery smoke scenarios passed');

