const CI_YML = Buffer.from('on:\n  workflow_dispatch:\n  pull_request:\njobs: {}\n').toString('base64');
const NO_DISPATCH_YML = Buffer.from('on:\n  pull_request:\njobs: {}\n').toString('base64');

function makeFetch(shape, calls) {
  return async (url, opts = {}) => {
    const method = opts.method ?? 'GET';
    const u = String(url);
    calls.push(`${method} ${u.replace('https://api.github.com', '')}`);
    const reply = (status, json) => ({ status, json: async () => json });

    if (u.endsWith('/graphql')) {
      return reply(200, shape.armError ? { errors: [{ message: shape.armError }] } : { data: {} });
    }
    if (u.includes('/contents/.github/workflows?')) {
      return reply(200, shape.workflows.map((w) => ({ name: w.name })));
    }
    if (u.includes('/contents/.github/workflows/')) {
      const name = decodeURIComponent(u.split('/contents/.github/workflows/')[1].split('?')[0]);
      const w = shape.workflows.find((x) => x.name === name);
      return reply(200, { content: w?.content ?? '' });
    }
    if (u.includes('/actions/workflows/') && u.endsWith('/dispatches')) return reply(204, null);
    if (u.includes('/branches/main')) return reply(200, { protected: shape.protected ?? false });
    if (u.includes('/rules/branches/main')) return reply(200, shape.rules ?? []);
    if (u.includes('/actions/runs?head_sha=')) return reply(200, { workflow_runs: shape.runs ?? [] });
    if (u.includes('/pulls/7/merge')) return reply(shape.mergeStatus ?? 200, { merged: true });
    if (u.includes('/git/refs/heads/')) return reply(204, null);
    throw new Error(`unstubbed: ${method} ${u}`);
  };
}

