// Smoke harness for the rewritten deliverGenerated(): real git plumbing against a
// local bare origin (same fixture shape as the committed test), GitHub REST stubbed.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { deliverGenerated } from '/home/user/Claudinite/engine/scheduler/deliver-generated.mjs';

function sh(cwd, ...args) {
  const r = spawnSync('git', args, { cwd, encoding: 'utf8' });
  assert.equal(r.status, 0, `git ${args.join(' ')}: ${r.stderr}`);
  return r.stdout;
}
function fixture(delivery) {
  const dir = mkdtempSync(join(tmpdir(), 'dg-smoke-'));
  const origin = join(dir, 'origin.git'); const work = join(dir, 'work');
  mkdirSync(origin); mkdirSync(work);
  sh(origin, 'init', '--bare', '--quiet', '--initial-branch=main');
  sh(work, 'init', '--quiet', '--initial-branch=main');
  sh(work, 'config', 'user.email', 't@t'); sh(work, 'config', 'user.name', 't');
  writeFileSync(join(work, '.claudinite-checks.json'),
    JSON.stringify({ packs: ['basics'], maintenance: { delivery } }, null, 2));
  sh(work, 'add', '-A'); sh(work, 'commit', '--quiet', '-m', 'base');
  sh(work, 'push', '--quiet', origin, 'main');
  return { dir, origin, work };
}

// deliverGenerated builds its own token remote URL; intercept the push by aliasing
// the URL to the local bare repo via git's insteadOf.
function aliasRemote(work, origin) {
  sh(work, 'config', `url.${origin}.insteadOf`, 'https://x-access-token:t@github.com/o/r.git');
}

function stubFetch(state) {
  global.fetch = async (url, opts = {}) => {
    const u = String(url); const method = opts.method ?? 'GET';
    state.calls.push(`${method} ${u.replace('https://api.github.com', '')}`);
    const reply = (status, json) => ({ status, json: async () => json });
    if (u.endsWith('/graphql')) return reply(200, { data: {} });
    if (u.includes('/pulls?state=open')) return reply(200, []);
    if (u.endsWith('/repos/o/r/pulls') && method === 'POST') {
      return reply(201, { number: 9, node_id: 'PR_9', head: { ref: JSON.parse(opts.body).head, sha: 'ignored' } });
    }
    if (u.includes('/contents/.github/workflows?')) return reply(404, { message: 'Not Found' }); // no CI dir
    if (u.includes('/rules/branches/main')) return reply(200, []);
    if (u.includes('/branches/main')) return reply(200, { protected: false });
    if (u.includes('/pulls/9/merge')) { state.mergedVia = 'PUT'; return reply(200, { merged: true }); }
    if (u.includes('/git/refs/heads/')) return reply(204, null);
    throw new Error(`unstubbed: ${method} ${u}`);
  };
}

const ARGS = (root) => ({
  root, repo: 'o/r', base: 'main', token: 't', branchPrefix: 'claudinite/gen', stamp: '2026-08-07',
  files: { 'out.GENERATED.json': '{"n":1}\n' }, title: 't', body: 'b', message: 'm', log: () => {},
});

// auto-merge repo, no PR CI → PR opened, merged directly, branch content correct.
{
  const { dir, origin, work } = fixture('auto-merge');
  aliasRemote(work, origin);
  const state = { calls: [], mergedVia: null };
  stubFetch(state);
  const out = await deliverGenerated(ARGS(work));
  assert.deepEqual({ delivery: out.delivery, merged: out.merged, number: out.number }, { delivery: 'auto-merge', merged: true, number: 9 });
  assert.equal(sh(origin, 'show', 'claudinite/gen/2026-08-07:out.GENERATED.json'), '{"n":1}\n');
  assert.equal(state.mergedVia, 'PUT');
  console.log('ok  auto-merge + no CI: pushed, PR opened, merged directly');
  rmSync(dir, { recursive: true, force: true });
}

// review repo → PR opened and LEFT; no merge, no arm.
{
  const { dir, origin, work } = fixture('review');
  aliasRemote(work, origin);
  const state = { calls: [], mergedVia: null };
  stubFetch(state);
  const out = await deliverGenerated(ARGS(work));
  assert.deepEqual({ delivery: out.delivery, merged: out.merged }, { delivery: 'review', merged: false });
  assert.ok(!state.calls.some((c) => c.includes('/merge') || c.includes('graphql')), `no merge/arm calls, got:\n${state.calls.join('\n')}`);
  console.log('ok  review: PR opened and left for the owner');
  rmSync(dir, { recursive: true, force: true });
}

// unrecognized delivery value → loud failure, nothing pushed.
{
  const { dir, origin, work } = fixture('bogus');
  aliasRemote(work, origin);
  stubFetch({ calls: [] });
  await assert.rejects(() => deliverGenerated(ARGS(work)), /neither auto-merge nor review/);
  assert.equal(spawnSync('git', ['show', 'claudinite/gen/2026-08-07:out.GENERATED.json'], { cwd: origin }).status === 0, false);
  console.log('ok  unrecognized delivery: fails loudly before pushing anything');
  rmSync(dir, { recursive: true, force: true });
}

console.log('\nall deliverGenerated smoke scenarios passed');

